[ExtensionOf(formStr(NDXTRUMPFParameters))]
final class NDXTRUMPFParameters_frm_Extension
{
    public NumberSeqReference                      numberSeqReference;
    public boolean                                 runExecuteDirect;
    public TmpIdRef                                tmpIdRef;
    public NumberSeqScope                          scope;
    public NumberSeqApplicationModule              numberSeqApplicationModule;
    public container                               numberSequenceModules;

}

Method.Source:
public void init()
{
    next init();
    new NDXNumberSeqNiedaxPDAModule().load();

    this.numberSeqPreInit();
}

void numberSeqPreInit()
{
    runExecuteDirect            = false;
    numberSequenceModules       = [NumberSeqModule::NDXTRUMPFPDA];
    numberSeqApplicationModule  = new NDXNumberSeqNiedaxPDAModule();
    scope = NumberSeqScopeFactory::createDataAreaScope();
    NumberSeqApplicationModule::createReferencesMulti(numberSequenceModules, scope);
    tmpIdRef.setTmpData(NumberSequenceReference::configurationKeyTableMulti(numberSequenceModules));
}
